def is_valid(isbn):
    chars = isbn.replace('-', '')
    digits = '0123456789'
    if len(chars) != 10 or any(char not in digits for char in chars[:9]):
        return False
    if chars[-1] not in digits + 'X':
        return False
    check = 10 if chars[-1] == 'X' else int(chars[-1])
    weighted_sum = sum((10 - index) * int(char) for index, char in enumerate(chars[:9]))
    return (weighted_sum + check) % 11 == 0
